    var st = stops[i];
    if (!(st[2] > 0)) continue;
    var r = Math.max(2, R * st[0]);
    var id = C.shape(c.graph, c.cut, c.cut.id + ' / ' + name + ' ' + i, c.parent,
      G.ellipse(0, 0, r, r), { fill: st[1], alpha: st[2] });
