      var xBase = W * ((idx + 0.5) / n + 0.3 * (N.random(seed, idx, 3) * 2 - 1)), yOff = N.random(seed, idx, 4) * span;
      var v = U * (0.006 + 0.01 * N.random(seed, idx, 5)), col = P.acc && idx % 4 === 1 ? c.sc.accent : c.sc.fg;
