  var ang = N.random(s.seed, 1, 1) < 0.65 ? (N.random(s.seed, 2, 1) < 0.5 ? 0 : PI) : (N.random(s.seed, 3, 1) < 0.5 ? 0.25 : 0.75) * PI;
