      var p = prog(f, s), x0 = p < 0.5 ? 0 : s.W * E.inOutCubic((p - 0.5) / 0.5), x1 = p < 0.5 ? s.W * E.inOutCubic(p / 0.5) : s.W;
      var rx0 = dir > 0 ? x0 : s.W - x1, rx1 = dir > 0 ? x1 : s.W - x0;
      if (rx1 - rx0 < 1) { cMap[f] = []; continue; }
      var polys = [];
