      var y0 = (li - (lines - 1) / 2) * lead - lead / 2;
      for (var b = 0; b < n; b++) {
        strips.push({ y0: y0 + b * lead / n, y1: y0 + (b + 1) * lead / n, k: dir * d * s * ((n - 1) / 2 - b) });
      }
